using System.Security.Cryptography;
namespace TSRPDiceModern;
internal static class Program { [STAThread] static void Main(){ ApplicationConfiguration.Initialize(); Application.Run(new DiceForm()); } }
public sealed class DiceForm:Form {
 readonly NumericUpDown count=new(){Minimum=1,Maximum=100,Value=1,Width=64}; readonly NumericUpDown mod=new(){Minimum=-999,Maximum=999,Width=72}; readonly ListBox history=new(){Dock=DockStyle.Fill}; readonly Label result=new(){Dock=DockStyle.Top,Height=90,TextAlign=ContentAlignment.MiddleCenter}; int sides=20;
 public DiceForm(){Text="AD&D Dice Roller";ClientSize=new(720,540);BackColor=Color.FromArgb(45,29,18);ForeColor=Color.Beige;Font=new("Segoe UI",10);var title=new Label{Text="AD&D DICE ROLLER",Dock=DockStyle.Top,Height=55,TextAlign=ContentAlignment.MiddleCenter,Font=new("Georgia",22,FontStyle.Bold),ForeColor=Color.Firebrick};result.Text="Choose a die and roll";result.Font=new("Georgia",24,FontStyle.Bold);result.BackColor=Color.Wheat;result.ForeColor=Color.FromArgb(45,29,18);var dice=new FlowLayoutPanel{Dock=DockStyle.Top,Height=70,Padding=new(10)};foreach(var s in new[]{4,6,8,10,12,20,100}){var b=new Button{Text=$"d{s}",Width=82,Height=44,Tag=s,Font=new("Georgia",12,FontStyle.Bold)};b.Click+=(_,_)=>sides=s;dice.Controls.Add(b);}var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=60,Padding=new(10),BackColor=Color.Wheat};bar.Controls.Add(new Label{Text="Dice:",AutoSize=true,ForeColor=Color.Black,Margin=new(3,8,3,0)});bar.Controls.Add(count);bar.Controls.Add(new Label{Text="Modifier:",AutoSize=true,ForeColor=Color.Black,Margin=new(12,8,3,0)});bar.Controls.Add(mod);var roll=new Button{Text="ROLL",Width=120,Height=36,BackColor=Color.Firebrick,ForeColor=Color.White,Margin=new(20,0,0,0)};roll.Click+=(_,_)=>Roll();bar.Controls.Add(roll);var panel=new Panel{Dock=DockStyle.Fill,Padding=new(12)};history.BackColor=Color.OldLace;history.ForeColor=Color.Black;history.Font=new("Consolas",10);panel.Controls.Add(history);Controls.Add(panel);Controls.Add(bar);Controls.Add(dice);Controls.Add(result);Controls.Add(title);AcceptButton=roll;}
 void Roll(){int n=(int)count.Value,m=(int)mod.Value,total=0;var r=new int[n];for(int i=0;i<n;i++){r[i]=RandomNumberGenerator.GetInt32(1,sides+1);total+=r[i];}total+=m;result.Text=total.ToString();string expr=$"{n}d{sides}{(m>0?$"+{m}":m<0?m.ToString():"")}";history.Items.Insert(0,$"{DateTime.Now:HH:mm:ss}  {expr,-10} [{string.Join(", ",r)}] => {total}");if(history.Items.Count>250)history.Items.RemoveAt(history.Items.Count-1);}
}
